structure.mermaidSource:
flowchart TD
  start["Localizar conectivo ou forma nominal"] --> dec_seta{"Teste da Seta: aponta para substantivo antecedente qualificando-o?"}
  dec_seta -- "Não" --> res_nao_adj["Não é Oração Adjetiva (Substantiva/Adverbial/Coord)"]
  dec_seta -- "Sim" --> dec_conectivo{"Possui pronome relativo expresso?"}
  dec_conectivo -- "Sim" --> res_desenv_exp["Oração Adjetiva Desenvolvida Explícita"]
  dec_conectivo -- "Não" --> dec_elipse{"Pronome relativo ou verbo está oculto/elíptico?"}
  dec_elipse -- "Sim" --> res_desenv_imp["Oração Adjetiva Desenvolvida Implícita"]
  dec_elipse -- "Não" --> dec_nominal{"Apresenta verbo em forma nominal sem conectivo?"}
  dec_nominal -- "Não" --> res_invalida["Construção Não Adjetiva / Estrutura Anômala"]
  dec_nominal -- "Sim" --> proc_descompactar["Executar Prova Real: descompactar com que + verbo flexionado"]
  proc_descompactar --> dec_prova_real{"Mantém sentido e correção após descompactação?"}
  dec_prova_real -- "Sim" --> res_reduzida["Oração Adjetiva Reduzida Confirmada"]
  dec_prova_real -- "Não" --> res_falsa_reduzida["Falsa Reduzida Adjetiva (Outra classificação)"]

flowchart TD
  start_p2(["Início: Oração Adjetiva sob análise"]) --> proc_isolar_adjetiva["1. Isolar Pronome Relativo e Antecedente"]
  proc_isolar_adjetiva --> dec_presenca_virgula{"A oração adjetiva está isolada por pontuação?"}
  dec_presenca_virgula -- "Sim (com vírgula/pontuação)" --> proc_classif_explicativa["Classificação: Oração Adjetiva Explicativa"]
  dec_presenca_virgula -- "Não (sem vírgula/pontuação)" --> proc_classif_restritiva["Classificação: Oração Adjetiva Restritiva"]
  proc_classif_explicativa --> dec_proposta_retirar{"A questão propõe RETIRAR as vírgulas?"}
  dec_proposta_retirar -- "Não (análise do texto original)" --> res_original_explicativa["DIAGNÓSTICO: Sentido Universal / Atributo da totalidade"]
  dec_proposta_retirar -- "Sim (proposta de supressão)" --> dec_antecedente_unico{"O antecedente é semanticamente único no universo?"}
  dec_antecedente_unico -- "Sim (ex: 'O Sol', nome próprio)" --> res_supressao_invalida["ERRO: Incorreção Gramatical e Incoerência Lógica"]
  dec_antecedente_unico -- "Não (substantivo comum amplo)" --> res_supressao_valida["ALTERAÇÃO DE SENTIDO: Correção mantida, sentido passa a Restritivo"]
  proc_classif_restritiva --> dec_proposta_inserir{"A questão propõe INSERIR vírgulas?"}
  dec_proposta_inserir -- "Não (análise do texto original)" --> res_original_restritiva["DIAGNÓSTICO: Sentido Restritivo / Delimita subconjunto"]
  dec_proposta_inserir -- "Sim (proposta de acréscimo)" --> res_insercao_valida["ALTERAÇÃO DE SENTIDO: Correção mantida, sentido passa a Explicativo"]

flowchart TD
  start["Localizar a vírgula suspeita no período"] --> dec_verbo_ant{"Há forma verbal na oração precedente?"}
  dec_verbo_ant -- "Não" --> res_sem_verbo["Sem Elipse Verbal (Vírgula de outra tipologia)"]
  dec_verbo_ant -- "Sim" --> proc_seta["Teste da Seta Anafórica: repor verbo anterior na vírgula"]
  proc_seta --> dec_seta_sentido{"A reposição do verbo confere sentido pleno?"}
  dec_seta_sentido -- "Não" --> res_falha_seta["Vírgula Não Vicária (Sem zeugma verbal)"]
  dec_seta_sentido -- "Sim" --> dec_classe_posposta{"Qual a classe gramatical do termo posposto?"}
  dec_classe_posposta -- "Substantivo" --> res_aposto["Aposto Explicativo (Equivalência nominal)"]
  dec_classe_posposta -- "Adjetivo ou Particípio" --> res_vicaria["Predicativo em Elipse Verbal (Vírgula Vicária - NUNCA aposto)"]

flowchart TD
  start["Localizar o Verbo Principal (Ancoragem Sintática)"] --> proc_mapear["Mapear Sujeito, Complementos e Termos Adverbiais"]
  proc_mapear --> dec_posicao{"Qual a posição sintática da vírgula avaliada?"}
  dec_posicao -- "Entre Sujeito e Verbo" --> res_sv_proibida["Vírgula PROIBIDA (Quebra Sujeito-Verbo)"]
  dec_posicao -- "Entre Verbo e Complemento" --> dec_tipo_comp{"O complemento é oração com que substituível por isso?"}
  dec_tipo_comp -- "Sim (OD Oracional)" --> res_integrante_proibida["Vírgula PROIBIDA (Entre Verbo e Conjunção Integrante)"]
  dec_tipo_comp -- "Não (Complemento Regular)" --> res_vc_proibida["Vírgula PROIBIDA (Entre Verbo e Complemento Nominal/Verbal)"]
  dec_posicao -- "Isolamento de Termo Adverbial" --> dec_pos_adverbial{"Qual a posição do termo adverbial no período?"}
  dec_pos_adverbial -- "Ao final da oração" --> res_adv_final["Vírgula FACULTATIVA (Posição canônica final)"]
  dec_pos_adverbial -- "Deslocado (início ou meio)" --> dec_adv_verbo{"O termo adverbial possui verbo (oração adverbial)?"}
  dec_adv_verbo -- "Sim (Oracional)" --> res_adv_oracional["Vírgula OBRIGATÓRIA (Oração Adverbial Deslocada)"]
  dec_adv_verbo -- "Não (Nominal)" --> dec_extensao{"Qual a extensão do adjunto adverbial?"}
  dec_extensao -- "Até 2 palavras" --> res_adv_curto["Vírgula FACULTATIVA (Curta extensão)"]
  dec_extensao -- "3 ou mais palavras" --> res_adv_longo["Vírgula OBRIGATÓRIA (Longa extensão)"]

flowchart TD
  start["Início: Identificar termo e vírgula sob análise"] -- "Analisar segmento" --> dec_1{"O segmento é oração adjetiva com pronome relativo?"}
  dec_1 -- "Sim" --> dec_adj_ref{"O referente possui natureza única ou múltipla?"}
  dec_adj_ref -- "Referente único" --> res_adj_unico["Prejuízo Gramatical e Semântico: Referente único não admite restrição"]
  dec_adj_ref -- "Referente múltiplo" --> res_adj_multiplo["Correção Mantida, Sentido Alterado: Converte-se em adjetiva restritiva"]
  dec_1 -- "Não" --> dec_2{"Trata-se de adjunto ou oração adverbial?"}
  dec_2 -- "Sim" --> dec_adv_pos{"Qual a posição e extensão do elemento adverbial?"}
  dec_adv_pos -- "Ordem direta (ao final)" --> res_adv_final["Correção e Sentido Mantidos: Vírgula facultativa no final do período"]
  dec_adv_pos -- "Deslocado curto (<= 2 palavras)" --> res_adv_curto["Correção e Sentido Mantidos: Vírgula facultativa por extensão curta"]
  dec_adv_pos -- "Deslocado longo (>= 3 palavras)" --> res_adv_longo["Prejuízo Gramatical: Vírgula obrigatória para adverbial longo anteposto"]
  dec_2 -- "Não" --> dec_3{"A vírgula antecede a conjunção 'e'?"}
  dec_3 -- "Sim" --> dec_e_tipo{"Qual o contexto da coordenação com 'e'?"}
  dec_e_tipo -- "Sujeitos distintos" --> res_e_distintos["Correção e Sentido Mantidos: Vírgula facultativa para sujeitos diferentes"]
  dec_e_tipo -- "Valor adversativo ('e' = 'mas')" --> res_e_adversativo["Prejuízo Semântico: Perda do contraste adversativo pretendido"]
  dec_e_tipo -- "Mesmo sujeito aditivo" --> res_e_mesmo["Correção Mantida: Padrão aditivo não exige vírgula"]
  dec_3 -- "Não" --> dec_4{"Isola aposto explicativo, vocativo ou conectivo adversativo?"}
  dec_4 -- "Sim" --> res_obrigatoria["Prejuízo Gramatical: Termo de isolamento obrigatório"]
  dec_4 -- "Não" --> res_proibida["Correção Mantida ou Restaurada: Vírgula separava termos diretos (S-V-O)"]
